def near(name: str, a: float, b: float, rtol: float = 1e-6, atol: float = 1e-9):
    if abs(a - b) > atol + rtol * abs(b):
        print("TEST FAILED:", name, a, b)


def test_ica_events():
    rng = np.random.RandomState(3)
    sf = 100.0
    info = mne.create_info(2, sf, "eeg")
    sig = np.zeros(3000)
    for k in range(5, 3000, 80):
        sig[k] = 1.0
        sig[k + 1] = 3.0
        sig[k + 2] = 1.0
    sig += 0.05 * rng.randn(3000)
    rr = mne.io.RawArray(np.vstack([sig, rng.randn(3000)]), info)
    ev = ica_find_ecg_events(rr, sig, event_id=999)
    assert ev.shape[0] == 37 and ev.shape[1] == 3
    assert int(ev[0, 0]) == 6 and int(ev[1, 0]) == 86 and int(ev[4, 0]) == 326 and int(ev[36, 0]) == 2886
    bl = np.zeros(3000)
    ar = np.arange(3000).astype(float)
    for k in range(100, 2900, 250):
        bl += 5 * np.exp(-0.5 * ((ar - k) / 8.0) ** 2)
    bl += 0.05 * rng.randn(3000)
    ev2 = ica_find_eog_events(rr, bl, event_id=998)
    assert ev2.shape[0] == 25
    assert int(ev2[0, 0]) == 27 and int(ev2[1, 0]) == 100 and int(ev2[2, 0]) == 267 and int(ev2[3, 0]) == 350

test_ica_events()


def test_score_funcs():
    rng = np.random.RandomState(3)
    # same stream as the generator: consume the preceding draws
    rng.randn(3000)
    rng.randn(3000)
    rng.randn(3000)
    x = rng.randn(3, 200)
    y = x[1] * 2 + 0.1 * rng.randn(200)
    sfn = get_score_funcs()
    ks = sfn.keys()
    assert ks[0] == "bws_test" and ks[4] == "pearsonr" and ks[6] == "spearmanrho" and len(ks) == 7
    p = sfn["pearsonr"](x, y)
    near("pr0", float(p[0]), 0.0, 1.0, 1.0)
    assert abs(float(p[1])) > 0.9
    s = sfn["spearmanrho"](x, y)
    assert abs(float(s[1])) > 0.9

test_score_funcs()


def make_pos():
    rng = np.random.RandomState(5)
    n = 30
    pos = np.zeros((n, 10))
    for i in range(n):
        pos[i, 0] = float(i)
    pos[:, 1:4] = np.cumsum(rng.randn(n, 3) * 0.01, axis=0)
    pos[:, 4:7] = np.cumsum(rng.randn(n, 3) * 0.002, axis=0)
    for i in range(10, 13):
        pos[i, 4] += 0.05
    return pos


def test_movement():
    info = mne.create_info(3, 100.0, "eeg")
    raw_m = mne.io.RawArray(np.zeros((3, 3000)), info)
    pos = make_pos()
    ann, _ = annotate_movement(raw_m, pos, rotation_velocity_limit=2.0, translation_velocity_limit=0.02)
    assert len(ann) == 7
    on = [3.0, 9.0, 12.0, 14.0, 18.0, 21.0, 25.0]
    du = [3.0, 1.0, 1.0, 1.0, 1.0, 3.0, 1.0]
    for i in range(7):
        near("on", ann.onset[i], on[i], 1e-9, 1e-9)
        near("du", ann.duration[i], du[i], 1e-9, 1e-9)
    assert ann.description[0] == "BAD_mov_rotat_vel" and ann.description[1] == "BAD_mov_trans_vel"
    t = compute_average_dev_head_t(raw_m, pos)
    exp = [0.9978566057941813, -0.06088443144702736, 0.02398500115255953, 0.005827007856803054,
           0.06075307525297147, 0.9981337658529332, 0.0061684124010059765, -0.004023469955521003,
           -0.024315799806357227, -0.004698028481642504, 0.9996932881680076, 0.004637022935511764,
           0.0, 0.0, 0.0, 1.0]
    for i in range(16):
        near("avgt", float(t[i // 4, i % 4]), exp[i], 1e-6, 1e-9)

test_movement()


def test_metadata():
    events = np.array([[100, 0, 1], [150, 0, 2], [220, 0, 3], [500, 0, 1], [530, 0, 3], [560, 0, 2], [900, 0, 1]])
    md, ev3, eid = make_metadata(events, {"a": 1, "b": 2, "c": 3}, -0.1, 0.5, 100.0)
    en = md.str_col("event_name")
    assert en[0] == "a" and en[1] == "b" and en[2] == "c" and en[4] == "c" and en[5] == "b"
    a = md["a"]
    b = md["b"]
    c = md["c"]
    assert a[0] == 0.0 and math.isnan(a[1]) and a[3] == 0.0 and a[6] == 0.0
    assert abs(b[0] - 0.5) < 1e-12 and b[1] == 0.0 and abs(b[4] - 0.3) < 1e-12 and b[5] == 0.0
    assert math.isnan(c[0]) and c[2] == 0.0 and abs(c[3] - 0.3) < 1e-12 and c[4] == 0.0
    assert ev3.shape[0] == 7
    md2, ev4, eid2 = make_metadata(events, {"a": 1, "b": 2, "c": 3}, None, None, 100.0, row_events=["a"])
    assert ev4.shape[0] == 3 and int(ev4[1, 0]) == 500
    b2 = md2["b"]
    c2 = md2["c"]
    assert abs(b2[0] - 0.5) < 1e-12 and abs(b2[1] - 0.6) < 1e-12 and math.isnan(b2[2])
    assert abs(c2[0] - 1.2) < 1e-12 and abs(c2[1] - 0.3) < 1e-12 and math.isnan(c2[2])
    assert len(eid2) == 1

test_metadata()


def test_rerp():
    rng = np.random.RandomState(7)
    info = mne.create_info(2, 50.0, "eeg")
    dat = rng.randn(2, 1500) * 0.1
    ev = np.array([[100, 0, 1], [400, 0, 2], [700, 0, 1], [1000, 0, 2], [1300, 0, 1]])
    h = np.hanning(20)
    for i in range(5):
        s = int(ev[i, 0])
        for k in range(20):
            for c in range(2):
                dat[c, s + k] += h[k] * (1 + ev[i, 2])
    rawr = mne.io.RawArray(dat, info)
    res = linear_regression_raw(rawr, ev, event_id={"a": 1, "b": 2}, tmin=-0.1, tmax=0.5)
    assert len(res) == 2
    assert res["a"].data.shape[0] == 2 and res["a"].data.shape[1] == 31
    assert res["b"].nave == 2
    near("rerp_a", float(res["a"].data.sum()), 37.9251675890131, 1e-6, 1e-9)
    near("rerp_b", float(res["b"].data.sum()), 56.89898520523278, 1e-6, 1e-9)
    near("rerp_b1_10", float(res["b"].data[1, 10]), 1.5784650991139573, 1e-6, 1e-9)

test_rerp()


def test_fmri():
    rng = np.random.RandomState(9)
    info = mne.create_info(3, 500.0, "eeg")
    d = rng.randn(3, 5000) * 0.1
    tr_len = 400
    tr = np.arange(0, 4800, tr_len)
    for s in tr:
        for k in range(tr_len):
            v = 5 * math.sin(2 * math.pi * k / 40.0) + 3.0 * k / (tr_len - 1)
            for c in range(3):
                d[c, s + k] += v
    rf = mne.io.RawArray(d, info)
    rc = remove_fmri_gradient_artifact(rf, tr, window=(2, 2))
    dc = rc.get_data()
    near("fmri_abs", float(np.abs(dc).sum()), 16095.371338843384, 1e-6, 1e-6)
    near("fmri_1_1000", float(dc[1, 1000]), -0.1268104519665923, 1e-6, 1e-6)
    near("fmri_0_4700", float(dc[0, 4700]), 0.21811611212496684, 1e-6, 1e-6)

test_fmri()


def test_realign():
    rng = np.random.RandomState(11)
    a = mne.io.RawArray(rng.randn(1, 6000), mne.create_info(1, 100.0, "eeg"))
    b = mne.io.RawArray(rng.randn(1, 6200), mne.create_info(1, 100.0, "eeg"))
    t_a = np.linspace(2.0, 50.0, 25)
    t_b = (t_a - 0.5) / 1.0005
    t_b = t_b + np.random.RandomState(1).randn(25) * 0.0005
    realign_raw(a, b, t_a, t_b)
    assert a.n_times == 5950 and b.n_times == 5950
    near("realign_a", float(a.get_data().sum()), 45.67881428013972, 1e-6, 1e-6)
    near("realign_b", float(b.get_data().sum()), -39.35977825956397, 1e-4, 1e-4)

test_realign()


