def test_pca_obs():
    rng = np.random.RandomState(17)
    n = 4000
    qrs = np.arange(100, n - 100, 160)
    ar = np.arange(-30, 31).astype(float)
    tmpl = np.exp(-0.5 * (ar / 6.0) ** 2) * 5
    d = rng.randn(2, n) * 0.3
    for q in qrs:
        sc = rng.randn(2, 1)
        for c in range(2):
            for k in range(61):
                d[c, q - 30 + k] += tmpl[k] * (1 + 0.1 * sc[c, 0])
    rp = mne.io.RawArray(d, mne.create_info(2, 200.0, "eeg"))
    rpo = apply_pca_obs(rp, picks=[0, 1], qrs_times=qrs / 200.0, n_components=2)
    near("pca_abs", float(np.abs(rpo.get_data()).sum()), 2341.3570074089994, 1e-5, 1e-5)
    near("pca_0_500", float(rpo.get_data()[0, 500]), -0.08574339056575625, 1e-5, 1e-5)
    near("pca_1_3000", float(rpo.get_data()[1, 3000]), 0.3867999389072728, 1e-5, 1e-5)

test_pca_obs()


def test_ica_io_corrmap():
    rng = np.random.RandomState(0)
    info = mne.create_info(5, 100.0, "eeg")
    rawi = mne.io.RawArray(rng.randn(5, 3000), info)
    ica = ICA(n_components=4, random_state=0, max_iter=200, method="infomax")
    ica.fit(rawi)
    ica.exclude = [1]
    p = "/tmp/typhon_final-ica.fif"
    ica.save(p, overwrite=True)
    i2 = read_ica(p)
    assert i2.n_components_ == 4
    assert i2.exclude[0] == 1
    assert i2.method == "infomax"
    assert abs(float(np.abs(i2.unmixing_matrix_ - ica.unmixing_matrix_).max())) < 1e-12
    assert abs(float(np.abs(i2.pca_components_ - ica.pca_components_).max())) < 1e-12
    assert i2.ch_names == ica.ch_names
    ica2 = ICA(n_components=4, random_state=1, max_iter=200, method="infomax")
    ica2.fit(rawi)
    icas = [ica, ica2]
    corrmap(icas, (0, 0), threshold=0.2, label="blink")
    assert icas[0].labels_["blink"][0] == 0
    assert icas[1].labels_["blink"][0] == 0

test_ica_io_corrmap()
